import {transport,dollars,textElement} from './transport.mjs';
export function unifiedRegistrationEnabled(){try{return JSON.parse(document.querySelector('#registration-orders-config')?.textContent||'{}').enabled===true;}catch{return false;}}
export async function initializeRegistrationDashboard(root=document.querySelector('main')||document.body){
 if(!unifiedRegistrationEnabled()||root.querySelector('#registrationOrdersDashboard'))return;
 const section=textElement('section','','bento_box registration-orders-dashboard');section.id='registrationOrdersDashboard';section.append(textElement('h2','My registrations'));
 const register=textElement('a','Register for a program','btn_main_wrap');register.href=location.hostname==='127.0.0.1'?'/registration-preview':'/program-registration';section.append(register);
 const notice=textElement('p','Loading your registrations…');notice.setAttribute('role','status');const list=document.createElement('div');section.append(notice,list);
 const old=root.querySelector('#listRegistration');const anchor=old?.closest('.bento_box')||old;if(anchor?.parentElement)anchor.before(section);else root.prepend(section);
 root.querySelectorAll('#add-registration-button').forEach(el=>{el.style.display='';el.setAttribute('href',register.href);});
 try{const api=transport(root),data=await api('account');notice.textContent=data.registrations.length?'':'Your confirmed registrations will appear here after checkout.';
 for(const item of data.registrations){const card=textElement('article','','registration-order-card');card.append(textElement('h3',item.student_name),textElement('p',`${item.program_name} · ${item.session_name}`),textElement('p',item.session_time),textElement('p',item.coverage_label),textElement('p',`Registration status: ${item.status_label}`));const order=data.orders.find(o=>o.order_id===item.order_id);if(order){card.append(textElement('p',`Amount paid for this registration: ${dollars(item.paid_cents||0)}`));if(item.payment_preference==='monthly')card.append(textElement('p',order.billing_followup==='Arranged'?'Your payment arrangement has been recorded by Chickenshed NYC.':'Deposit received. Chickenshed NYC will contact you to arrange monthly payments.'));if(item.payment_preference==='semester')card.append(textElement('p',order.billing_followup==='Arranged'?'Your semester payment arrangement has been recorded by Chickenshed NYC.':'Pay per semester selected. Chickenshed NYC will follow up about remaining or later semester payments.'));const receipt=textElement('a','View order');receipt.href=(location.hostname==='127.0.0.1'?'/registration-success-preview':'/checkout-success/registration-order')+'?session_id='+encodeURIComponent(item.receipt_session_id);card.append(receipt);}
 if(item.resources_available){const button=textElement('button','Class files and resources');button.type='button';const files=document.createElement('div');button.addEventListener('click',async()=>{button.disabled=true;files.replaceChildren(textElement('p','Loading resources…'));try{const rows=await api('resources?registration_id='+encodeURIComponent(item.registration_id));files.replaceChildren();if(!rows.length)files.append(textElement('p','No class resources have been shared yet.'));for(const file of rows){let url;try{url=new URL(file.url);}catch{continue;}if(url.protocol!=='https:')continue;const link=textElement('a',file.name||'Class resource');link.href=url.href;link.target='_blank';link.rel='noopener';files.append(link);}}catch(e){files.replaceChildren(textElement('p',e.message));}finally{button.disabled=false;}});card.append(button,files);}list.append(card);}
 }catch(e){notice.textContent=e.message;}
}
